import{_ as e,o as a,c as o,a5 as r}from"./chunks/framework.BMR-TWOq.js";const h="/RBQ/nightly/images/operation/status-lights.en.svg",u=JSON.parse('{"title":"Status Lights","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/operation/status-lights.md","filePath":"manual/operation/status-lights.md","lastUpdated":1794576042000}'),n={name:"manual/operation/status-lights.md"};function d(s,t,l,i,c,g){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="status-lights" tabindex="-1">Status Lights <a class="header-anchor" href="#status-lights" aria-label="Permalink to &quot;Status Lights&quot;">​</a></h1><p>The lights on the top panel show the robot&#39;s state at a glance, even with no controller connected. The four cells of the top row are the battery level (1). The bottom row, from the left, is E-STOP (2), communication module (3), control mode (4) and network (5).</p><figure><img style="max-width:100%;width:min(480px, 100%);height:auto;display:block;margin:1rem auto;" src="'+h+'" alt="Top panel lights: 1 battery level (top row, 4 cells); bottom row from the left 2 E-STOP, 3 communication module, 4 control mode, 5 network"><figcaption style="text-align:center;">[ Top panel lights (schematic) ]</figcaption></figure><table tabindex="0"><thead><tr><th>No.</th><th>Light</th><th>What it shows</th></tr></thead><tbody><tr><td>1</td><td>Battery (4 cells)</td><td>Remaining charge, charging and battery faults</td></tr><tr><td>2</td><td>E-STOP</td><td>Whether the robot is in emergency stop</td></tr><tr><td>3</td><td>Communication module</td><td>Whether the robot PC can reach the communication module</td></tr><tr><td>4</td><td>Control mode</td><td>Who drives the robot, and docking</td></tr><tr><td>5</td><td>Network</td><td>Data on the U-PC and R-PC network</td></tr></tbody></table><p>For the first 10 seconds after power-on, every light except the network light is off.</p><h2 id="battery" tabindex="-1">Battery <a class="header-anchor" href="#battery" aria-label="Permalink to &quot;Battery {#battery}&quot;">​</a></h2><p>The four cells show the charge left in both battery packs together. Each cell stands for 25 %, and a cell lights as soon as its share has started: 60 % lights three cells.</p><table tabindex="0"><thead><tr><th>Display</th><th>Meaning</th><th>What to do</th></tr></thead><tbody><tr><td>Green, steady</td><td>Normal. The number of cells is the charge left</td><td>—</td></tr><tr><td>Red, steady</td><td>One pack cannot be used: it is not detected, or the two packs are not sharing the load evenly. A pack that is not detected is left out of the charge, so the gauge shows at most two cells</td><td>Check the packs in the app</td></tr><tr><td>One orange cell, fast blink</td><td>10 % or less. The robot will shut down soon</td><td>Charge now</td></tr><tr><td>All four red, fast blink</td><td>Battery protection is active: over-voltage, under-voltage, over-current, short circuit or overheating</td><td>Stop the robot and check the battery in the app</td></tr><tr><td>All off</td><td>No battery information is coming in</td><td>Check the battery in the app</td></tr></tbody></table><h3 id="battery-charging" tabindex="-1">While charging <a class="header-anchor" href="#battery-charging" aria-label="Permalink to &quot;While charging {#battery-charging}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Display</th><th>Meaning</th></tr></thead><tbody><tr><td>Last lit cell, slow blink</td><td>Charging</td></tr><tr><td>All lit cells steady</td><td>Charging is complete (99 % or more), or the packs are full and charging has stopped</td></tr><tr><td>Last lit cell red, fast blink</td><td>Charging fault: the charging current has stayed below 0.2 A for 60 seconds while the charge is below 90 %. Check the charger or docking station connection</td></tr></tbody></table><h3 id="battery-health" tabindex="-1">Battery health at power-on <a class="header-anchor" href="#battery-health" aria-label="Permalink to &quot;Battery health at power-on {#battery-health}&quot;">​</a></h3><p>If a pack&#39;s health (SOH) is below 80 %, all four cells light orange from 10 to 30 seconds after power-on. The pack still works, but it has aged. Plan to replace it.</p><h2 id="status" tabindex="-1">Status lights <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status lights {#status}&quot;">​</a></h2><p>Each status light shows one thing. Green means normal.</p><table tabindex="0"><thead><tr><th>Light</th><th>Green, steady</th><th>Other</th></tr></thead><tbody><tr><td>E-STOP</td><td>Normal</td><td><strong>Red, steady</strong> — emergency stop: the button, <code>E-STOP</code> in the app, a fall, or a critical fault. To recover, see <a href="/RBQ/nightly/manual/operation/emo.html">Emergency Stop and Recovery</a></td></tr><tr><td>Communication module</td><td>The robot PC reaches the communication module</td><td><strong>Red, steady</strong> — the robot PC cannot reach the communication module, or the installed option reports a lost link (the dashboard&#39;s <code>Option status</code> card shows which). Check the module&#39;s power and cable</td></tr><tr><td>Control mode</td><td>Controller mode</td><td><strong>Blue, steady</strong> — external control (SLAM or SDK) is driving the robot. <strong>Slow blink</strong> — docking, in the colour of the current mode</td></tr></tbody></table><h3 id="pc" tabindex="-1">Robot PC starting or not responding <a class="header-anchor" href="#pc" aria-label="Permalink to &quot;Robot PC starting or not responding {#pc}&quot;">​</a></h3><p>When the robot PC is off, the panel takes over the three status lights.</p><table tabindex="0"><thead><tr><th>Display</th><th>Meaning</th><th>What to do</th></tr></thead><tbody><tr><td>White, moving across the three lights</td><td>The robot PC is starting</td><td>Wait. After a software restart this also appears for a short time</td></tr><tr><td>All three red, fast blink</td><td>The robot PC is not responding: it stopped, or did not start within 2 minutes</td><td>Restart the robot</td></tr></tbody></table><h3 id="lamp-test" tabindex="-1">Lamp test <a class="header-anchor" href="#lamp-test" aria-label="Permalink to &quot;Lamp test {#lamp-test}&quot;">​</a></h3><p>The battery and status lights turn red, then green, then blue for 1.6 seconds when the robot software starts, and when you run <code>Lamp test</code> in the app (<a href="/RBQ/nightly/manual/gui/maintenance.html#led-bottom">Maintenance</a>). Use it to check that every light works.</p><h2 id="network" tabindex="-1">Network light <a class="header-anchor" href="#network" aria-label="Permalink to &quot;Network light {#network}&quot;">​</a></h2><p>The network light holds two small lights. Red blinks while data passes through the U-PC (user PC), and blue blinks while data passes through the R-PC (robot PC). The hardware drives this light directly, so it cannot be turned off. For the network layout, see <a href="/RBQ/nightly/manual/interface/network.html">Network</a>.</p>',22)])])}const b=e(n,[["render",d]]);export{u as __pageData,b as default};
